		"a b",   // space
		"a.b",   // punctuation
		"a/b",   // slash
		"日本",    // non-ASCII
		"café",  // non-ASCII byte
		"a\nb",  // control character
		"a--b ", // trailing space
	}
	for _, name := range bad {
		root := New("tool", "", nil, noop)
		err := root.Add(New(name, "", nil, noop))
		if !errors.Is(err, ErrInvalidName) {
			t.Errorf("Add(%q) error = %v, want errors.Is ErrInvalidName", name, err)
